sys_script_include.script:
var HelloWorld = Class.create();
HelloWorld.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    helloWorld: function() {
        var todo = new GlideRecord('x_1634320_to_do_to_do');
        todo.addQuery('sys_id', this.getParameter('sysparm_sys_id'));
        todo.query();
        while (todo.next()) {
            gs.info('********* to_do_item is:   : ' + todo.to_do_item);
            //gs.info('Hardware name: ' + todo.name);
            todo.to_do_item = this.getParameter('sysparm_to_do_item');
            //wAsset.assigned_to = newimp;
            todo.update();
        }
        return "Hello " + this.getParameter('sysparm_user_name') + "!";
    },
    _privateFunction: function() { // this function is not client callable     
    }
});
